import React from "react";
import { cn } from "@/lib/utils";
import Switch from "@/components/switch";
import Label from "@/components/label";
import { FormikErrorText } from "./formik-error-text";
import { getNestedValue } from "./utils";

interface FormikSwitchProps {
  id: string;
  formik: any;
  label?: string | React.ReactNode;
  disabled?: boolean;
  className?: string;
  containerClassName?: string;
  labelClassName?: string;
  labelSide?: "left" | "right";
  onChange?: (checked: boolean) => void;
}

export const FormikSwitch: React.FC<FormikSwitchProps> = ({
  id,
  formik,
  label,
  disabled,
  className,
  containerClassName,
  labelClassName,
  labelSide = "left",
  onChange,
}) => (
  <div className={cn("flex flex-col text-start gap-4", containerClassName)}>
    {label && labelSide === "left" && (
      <Label htmlFor={id} className={cn(labelClassName)}>
        {label}
      </Label>
    )}
    <div className="flex items-center gap-2">
      <Switch
        id={id}
        checked={getNestedValue(formik.values, id) ?? false}
        onChange={(checked) => {
          formik.setFieldValue(id, checked);
          onChange?.(checked);
        }}
        disabled={disabled}
        className={cn(className)}
      />
      {label && labelSide === "right" && (
        <Label htmlFor={id} className={cn(labelClassName)}>
          {label}
        </Label>
      )}
    </div>
    <FormikErrorText id={id} formik={formik} />
  </div>
);

/* eslint-disable @typescript-eslint/no-explicit-any */
import React from "react";
import { formikErrorCheck } from "./utils";

interface FormikErrorTextProps {
  id: string;
  formik: any;
}

export const FormikErrorText: React.FC<FormikErrorTextProps> = ({
  id,
  formik,
}) => {
  const errorMessage = formikErrorCheck(formik, id);

  return errorMessage ? (
    <span className="text-xs font-medium text-red-500">{errorMessage}</span>
  ) : (
    <span className="text-xs font-medium text-red-500">&nbsp;</span>
  );
};

/* eslint-disable @typescript-eslint/no-explicit-any */

export function getNestedValue(obj: any, path: string): any {
  if (!obj || !path) return undefined;
  return path.split(".").reduce((acc, key) => acc?.[key], obj);
}

export function formikErrorCheck(formik: any, id: string): string | undefined {
  const touched = getNestedValue(formik.touched, id);
  const error = getNestedValue(formik.errors, id);
  if (touched && error) {
    return typeof error === "object" && error.text ? error.text : error;
  }
  return undefined;
}

export { FormikTextField } from "./formik-text-field";
export { FormikSelect } from "./formik-select";
export { FormikCheckbox } from "./formik-checkbox";
export { FormikDatePicker } from "./formik-date-picker";
export { FormikRadioButtons } from "./formik-radio-buttons";
export { FormikSwitch } from "./formik-switch";
export { FormikErrorText } from "./formik-error-text";
export { getNestedValue } from "./utils";
